//! End-to-end encrypted team protocol primitives.
//!
//! # Key hierarchy
//!
//! 1. Each developer has an X25519 identity key pair, generated locally. The
//!    private half lives in the OS credential store; the public half is
//!    registered with the sync server.
//! 2. A team owns a random 256-bit team key (TK), generated by the team owner.
//!    Team payloads are encrypted with TK using ChaCha20-Poly1305.
//! 3. TK is distributed to members as *sealed envelopes*: the sender generates
//!    an ephemeral X25519 key pair, performs ECDH with the recipient's public
//!    key, derives a wrapping key with HKDF-SHA256, and encrypts TK with the
//!    recipient id, team id and epoch bound as AAD.
//!
//! The server only ever receives public keys, sealed envelopes and ciphertext.
//! It cannot derive TK and cannot read a team payload.

use std::collections::BTreeMap;

use base64::engine::general_purpose::STANDARD_NO_PAD;
use base64::Engine;
use hkdf::Hkdf;
use serde::{Deserialize, Serialize};
use sha2::Sha256;
use x25519_dalek::{PublicKey, StaticSecret};
use zeroize::{Zeroize, Zeroizing};

use crate::crypto;
use crate::error::{CoreError, Result};
use crate::secret::SecretValue;
use crate::vault::{now_unix, validate_name, validate_value, Entry};

pub const TEAM_SCHEMA_VERSION: u32 = 1;

fn b64_encode(bytes: &[u8]) -> String {
    STANDARD_NO_PAD.encode(bytes)
}

fn b64_decode(input: &str, field: &str) -> Result<Vec<u8>> {
    STANDARD_NO_PAD.decode(input).map_err(|_| {
        CoreError::InvalidCrypto(match field {
            "ephemeral_public" => "ephemeral public key is not valid base64",
            "nonce" => "envelope nonce is not valid base64",
            "ciphertext" => "envelope ciphertext is not valid base64",
            _ => "invalid base64 field",
        })
    })
}

/// A local X25519 identity for team sync.
pub struct TeamIdentity {
    secret: Zeroizing<[u8; crypto::KEY_LEN]>,
    public: [u8; crypto::KEY_LEN],
}

impl TeamIdentity {
    pub fn generate() -> Result<Self> {
        let secret = crypto::random_key()?;
        Ok(Self::from_secret(&secret[..])?)
    }

    pub fn from_secret(bytes: &[u8]) -> Result<Self> {
        if bytes.len() != crypto::KEY_LEN {
            return Err(CoreError::InvalidCrypto(
                "X25519 identity secret must be 32 bytes",
            ));
        }
        let mut secret = Zeroizing::new([0u8; crypto::KEY_LEN]);
        secret.copy_from_slice(bytes);
        let static_secret = StaticSecret::from(*secret);
        let public = PublicKey::from(&static_secret);
        Ok(Self {
            secret,
            public: public.to_bytes(),
        })
    }

    pub fn secret(&self) -> &[u8; crypto::KEY_LEN] {
        &self.secret
    }

    pub fn public(&self) -> &[u8; crypto::KEY_LEN] {
        &self.public
    }

    pub fn public_base64(&self) -> String {
        b64_encode(&self.public)
    }
}

impl std::fmt::Debug for TeamIdentity {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str("TeamIdentity([REDACTED])")
    }
}

/// A team key sealed for one recipient at one epoch.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct SealedTeamKey {
    pub recipient: String,
    pub epoch: u32,
    #[serde(rename = "ephemeral_public_key")]
    pub ephemeral_public: String,
    pub nonce: String,
    pub ciphertext: String,
}

fn envelope_aad(team_id: &str, epoch: u32, recipient: &str) -> String {
    format!("velt-team-key-v1|{team_id}|{epoch}|{recipient}")
}

/// Encrypt `team_key` for a recipient's X25519 public key.
pub fn seal_team_key(
    recipient_public: &[u8; crypto::KEY_LEN],
    team_id: &str,
    epoch: u32,
    recipient: &str,
    team_key: &[u8; crypto::KEY_LEN],
) -> Result<SealedTeamKey> {
    if team_id.is_empty() || recipient.is_empty() {
        return Err(CoreError::InvalidCrypto(
            "team id and recipient are required for key sealing",
        ));
    }
    // Ephemeral key pair: generated per envelope and discarded after use.
    let ephemeral_secret = crypto::random_key()?;
    let ephemeral = StaticSecret::from(*ephemeral_secret);
    let recipient_public = PublicKey::from(*recipient_public);
    let shared = ephemeral.diffie_hellman(&recipient_public);
    if !shared.was_contributory() {
        return Err(CoreError::InvalidCrypto(
            "recipient public key is a low-order X25519 point",
        ));
    }

    let aad = envelope_aad(team_id, epoch, recipient);
    let hkdf = Hkdf::<Sha256>::new(Some(b"velt-team-key-wrap-salt-v1"), shared.as_bytes());
    let mut wrapping_key = Zeroizing::new([0u8; crypto::KEY_LEN]);
    hkdf.expand(aad.as_bytes(), &mut wrapping_key[..])
        .map_err(|_| CoreError::InvalidCrypto("HKDF expansion failed"))?;

    let nonce = crypto::random_nonce()?;
    let ciphertext = crypto::encrypt(&wrapping_key, &nonce, aad.as_bytes(), team_key)?;
    let ephemeral_public = PublicKey::from(&ephemeral).to_bytes();

    Ok(SealedTeamKey {
        recipient: recipient.to_owned(),
        epoch,
        ephemeral_public: b64_encode(&ephemeral_public),
        nonce: b64_encode(&nonce),
        ciphertext: b64_encode(&ciphertext),
    })
}

/// Decrypt a sealed team key with the local identity secret.
pub fn open_team_key(
    identity_secret: &[u8; crypto::KEY_LEN],
    team_id: &str,
    sealed: &SealedTeamKey,
) -> Result<Zeroizing<[u8; crypto::KEY_LEN]>> {
    let ephemeral_bytes = b64_decode(&sealed.ephemeral_public, "ephemeral_public")?;
    if ephemeral_bytes.len() != 32 {
        return Err(CoreError::InvalidCrypto(
            "ephemeral public key must be 32 bytes",
        ));
    }
    let mut ephemeral = [0u8; 32];
    ephemeral.copy_from_slice(&ephemeral_bytes);
    let nonce_bytes = b64_decode(&sealed.nonce, "nonce")?;
    if nonce_bytes.len() != crypto::NONCE_LEN {
        return Err(CoreError::InvalidCrypto("envelope nonce must be 12 bytes"));
    }
    let mut nonce = [0u8; crypto::NONCE_LEN];
    nonce.copy_from_slice(&nonce_bytes);
    let ciphertext = b64_decode(&sealed.ciphertext, "ciphertext")?;

    let identity = StaticSecret::from(*identity_secret);
    let shared = identity.diffie_hellman(&PublicKey::from(ephemeral));
    if !shared.was_contributory() {
        return Err(CoreError::InvalidCrypto(
            "ephemeral public key is a low-order X25519 point",
        ));
    }
    let aad = envelope_aad(team_id, sealed.epoch, &sealed.recipient);
    let hkdf = Hkdf::<Sha256>::new(Some(b"velt-team-key-wrap-salt-v1"), shared.as_bytes());
    let mut wrapping_key = Zeroizing::new([0u8; crypto::KEY_LEN]);
    hkdf.expand(aad.as_bytes(), &mut wrapping_key[..])
        .map_err(|_| CoreError::InvalidCrypto("HKDF expansion failed"))?;

    let plaintext = crypto::decrypt(&wrapping_key, &nonce, aad.as_bytes(), &ciphertext)?;
    if plaintext.len() != crypto::KEY_LEN {
        return Err(CoreError::InvalidCrypto(
            "sealed team key has an invalid length",
        ));
    }
    let mut team_key = Zeroizing::new([0u8; crypto::KEY_LEN]);
    team_key.copy_from_slice(&plaintext);
    Ok(team_key)
}

#[derive(Serialize)]
struct TeamPayloadBody<'a> {
    schema: u32,
    team_id: &'a str,
    environment: &'a str,
    updated_at: i64,
    entries: &'a BTreeMap<String, Entry>,
}

/// Plaintext team payload, always encrypted before leaving the machine.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct TeamPayload {
    pub schema: u32,
    pub team_id: String,
    pub environment: String,
    pub updated_at: i64,
    pub entries: BTreeMap<String, Entry>,
    #[serde(default)]
    pub checksum: String,
}

impl TeamPayload {
    pub fn new(
        team_id: impl Into<String>,
        environment: impl Into<String>,
        entries: BTreeMap<String, Entry>,
    ) -> Self {
        Self {
            schema: TEAM_SCHEMA_VERSION,
            team_id: team_id.into(),
            environment: environment.into(),
            updated_at: now_unix(),
            entries,
            checksum: String::new(),
        }
    }

    fn body(&self) -> TeamPayloadBody<'_> {
        TeamPayloadBody {
            schema: self.schema,
            team_id: &self.team_id,
            environment: &self.environment,
            updated_at: self.updated_at,
            entries: &self.entries,
        }
    }

    pub fn compute_checksum(&self) -> Result<String> {
        let canonical = serde_json::to_vec(&self.body())?;
        Ok(hex::encode(crypto::sha256(&canonical)))
    }

    fn verify_checksum(&self) -> Result<()> {
        if self.checksum.is_empty() {
            return Err(CoreError::InvalidVault(
                "team payload is missing its checksum".to_owned(),
            ));
        }
        let expected = self.compute_checksum()?;
        let expected = hex::decode(expected)
            .map_err(|_| CoreError::InvalidVault("team checksum is invalid".to_owned()))?;
        let actual = hex::decode(&self.checksum)
            .map_err(|_| CoreError::InvalidVault("team checksum is invalid".to_owned()))?;
        if !crypto::constant_time_eq(&expected, &actual) {
            return Err(CoreError::InvalidVault(
                "team payload checksum mismatch".to_owned(),
            ));
        }
        Ok(())
    }

    /// Encrypt the payload with the team key. The returned checksum is over the
    /// ciphertext and is safe to give the relay for integrity checks.
    pub fn encrypt(&mut self, team_key: &[u8; crypto::KEY_LEN]) -> Result<EncryptedTeamPayload> {
        self.checksum = self.compute_checksum()?;
        let body = Zeroizing::new(serde_json::to_vec(self)?);
        let aad = blob_aad(&self.team_id, &self.environment);
        let nonce = crypto::random_nonce()?;
        let ciphertext = crypto::encrypt(team_key, &nonce, aad.as_bytes(), &body)?;
        drop(body);
        let checksum = crypto::sha256(&ciphertext);
        Ok(EncryptedTeamPayload {
            nonce,
            ciphertext,
            checksum,
        })
    }

    /// Decrypt and validate a team payload.
    pub fn decrypt(
        team_key: &[u8; crypto::KEY_LEN],
        team_id: &str,
        environment: &str,
        nonce: &[u8; crypto::NONCE_LEN],
        ciphertext: &[u8],
    ) -> Result<Self> {
        let aad = blob_aad(team_id, environment);
        let mut plaintext = crypto::decrypt(team_key, nonce, aad.as_bytes(), ciphertext)?;
        let payload: Self = serde_json::from_slice(plaintext.as_slice())?;
        plaintext.zeroize();
        if payload.schema != TEAM_SCHEMA_VERSION {
            return Err(CoreError::InvalidVault(format!(
                "unsupported team payload schema {}",
                payload.schema
            )));
        }
        if payload.team_id != team_id || payload.environment != environment {
            return Err(CoreError::InvalidVault(
                "team payload is bound to a different team or environment".to_owned(),
            ));
        }
        if payload.entries.len() > 100_000 {
            return Err(CoreError::InvalidVault(
                "team payload contains too many entries".to_owned(),
            ));
        }
        for (name, entry) in &payload.entries {
            validate_name(name)?;
            validate_value(name, entry.value.expose())?;
        }
        payload.verify_checksum()?;
        Ok(payload)
    }

    pub fn into_entries(self) -> BTreeMap<String, Entry> {
        self.entries
    }
}

fn blob_aad(team_id: &str, environment: &str) -> String {
    format!("velt-team-blob-v1|{team_id}|{environment}")
}

/// Ciphertext ready to upload to the relay.
#[derive(Clone, Debug)]
pub struct EncryptedTeamPayload {
    pub nonce: [u8; crypto::NONCE_LEN],
    pub ciphertext: Vec<u8>,
    pub checksum: [u8; 32],
}

impl EncryptedTeamPayload {
    pub fn nonce_base64(&self) -> String {
        b64_encode(&self.nonce)
    }

    pub fn ciphertext_base64(&self) -> String {
        b64_encode(&self.ciphertext)
    }

    pub fn checksum_hex(&self) -> String {
        hex::encode(self.checksum)
    }

    pub fn checksum_base64(&self) -> String {
        b64_encode(&self.checksum)
    }
}

/// Create an entry for a team payload from a plaintext secret.
pub fn team_entry(value: impl Into<SecretValue>, expires_at: Option<i64>) -> Entry {
    Entry {
        value: value.into(),
        updated_at: now_unix(),
        expires_at,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn team_key() -> [u8; 32] {
        [7u8; 32]
    }

    fn entries() -> BTreeMap<String, Entry> {
        let mut entries = BTreeMap::new();
        entries.insert(
            "DATABASE_URL".to_owned(),
            team_entry("postgres://localhost/app", None),
        );
        entries.insert("API_KEY".to_owned(), team_entry("super-secret", None));
        entries
    }

    #[test]
    fn envelope_roundtrip() {
        let identity = TeamIdentity::generate().unwrap();
        let sealed = seal_team_key(identity.public(), "team-1", 3, "alice", &team_key()).unwrap();
        let opened = open_team_key(identity.secret(), "team-1", &sealed).unwrap();
        assert_eq!(&opened[..], &team_key());
    }

    #[test]
    fn wrong_identity_cannot_open() {
        let alice = TeamIdentity::generate().unwrap();
        let bob = TeamIdentity::generate().unwrap();
        let sealed = seal_team_key(alice.public(), "team-1", 1, "alice", &team_key()).unwrap();
        assert!(open_team_key(bob.secret(), "team-1", &sealed).is_err());
    }

    #[test]
    fn envelope_is_bound_to_team_and_epoch() {
        let identity = TeamIdentity::generate().unwrap();
        let sealed = seal_team_key(identity.public(), "team-1", 1, "alice", &team_key()).unwrap();
        assert!(open_team_key(identity.secret(), "team-2", &sealed).is_err());

        let mut tampered = sealed;
        tampered.epoch = 2;
        assert!(open_team_key(identity.secret(), "team-1", &tampered).is_err());
    }

    #[test]
    fn identity_public_key_is_stable() {
        let first = TeamIdentity::from_secret(&[5u8; 32]).unwrap();
        let second = TeamIdentity::from_secret(&[5u8; 32]).unwrap();
        assert_eq!(first.public(), second.public());
    }

    #[test]
    fn team_payload_roundtrip() {
        let mut payload = TeamPayload::new("team-1", "production", entries());
        let encrypted = payload.encrypt(&team_key()).unwrap();
        let decrypted = TeamPayload::decrypt(
            &team_key(),
            "team-1",
            "production",
            &encrypted.nonce,
            &encrypted.ciphertext,
        )
        .unwrap();
        assert_eq!(decrypted.entries.len(), 2);
        assert_eq!(decrypted.entries["API_KEY"].value.expose(), "super-secret");
        assert_eq!(decrypted.checksum, payload.checksum);
    }

    #[test]
    fn team_payload_is_bound_to_environment() {
        let mut payload = TeamPayload::new("team-1", "production", entries());
        let encrypted = payload.encrypt(&team_key()).unwrap();
        assert!(TeamPayload::decrypt(
            &team_key(),
            "team-1",
            "staging",
            &encrypted.nonce,
            &encrypted.ciphertext,
        )
        .is_err());
    }

    #[test]
    fn tampered_team_ciphertext_fails() {
        let mut payload = TeamPayload::new("team-1", "production", entries());
        let mut encrypted = payload.encrypt(&team_key()).unwrap();
        encrypted.ciphertext[0] ^= 1;
        assert!(TeamPayload::decrypt(
            &team_key(),
            "team-1",
            "production",
            &encrypted.nonce,
            &encrypted.ciphertext,
        )
        .is_err());
    }

    #[test]
    fn decrypted_payload_checksum_is_verified() {
        // Build a payload with a bad checksum and encrypt it directly.
        let mut payload = TeamPayload::new("team-1", "production", entries());
        payload.checksum = "00".repeat(32);
        let body = Zeroizing::new(serde_json::to_vec(&payload).unwrap());
        let nonce = crypto::random_nonce().unwrap();
        let aad = blob_aad("team-1", "production");
        let ciphertext = crypto::encrypt(&team_key(), &nonce, aad.as_bytes(), &body).unwrap();
        assert!(
            TeamPayload::decrypt(&team_key(), "team-1", "production", &nonce, &ciphertext,)
                .is_err()
        );
    }
}
